//! The management key (ENK-OWN-014, ENK-OWN-015): generated by the device, at least 80 bits of
//! randomness, at most 24 characters, no characters that are easily mistaken for one another.
//!
//! Form: four groups of five characters joined by hyphens, 23 characters in all. The alphabet
//! has 31 symbols (lower-case letters and digits without `0 o 1 l i`), so 20 symbols carry
//! 20 × log2(31) ≈ 99 bits.

/// Symbols that are not mistaken for one another on a phone screen or a printed note.
pub const ALPHABET: &[u8; 31] = b"abcdefghjkmnpqrstuvwxyz23456789";

/// Symbols in a key, hyphens excluded.
pub const SYMBOLS: usize = 20;

/// Symbols per hyphenated group.
pub const GROUP: usize = 5;

/// Largest random byte accepted without bias: the greatest multiple of 31 not above 256.
const ACCEPT_BELOW: u8 = (256 / 31 * 31) as u8; // 248

/// Builds a key from a stream of random bytes with rejection sampling, so that every symbol is
/// uniform. Returns `None` if the stream ends first (a caller supplies plenty).
pub fn management_key_from_random<I: Iterator<Item = u8>>(random: I) -> Option<String> {
    let mut symbols = Vec::with_capacity(SYMBOLS);
    for byte in random {
        if byte < ACCEPT_BELOW {
            symbols.push(ALPHABET[(byte % 31) as usize]);
            if symbols.len() == SYMBOLS {
                break;
            }
        }
    }
    if symbols.len() < SYMBOLS {
        return None;
    }
    let groups: Vec<String> = symbols
        .chunks(GROUP)
        .map(|g| String::from_utf8(g.to_vec()).expect("ascii alphabet"))
        .collect();
    Some(groups.join("-"))
}

/// Whether a string has the form this module produces.
pub fn is_management_key(candidate: &str) -> bool {
    let groups: Vec<&str> = candidate.split('-').collect();
    groups.len() == SYMBOLS / GROUP
        && groups
            .iter()
            .all(|g| g.len() == GROUP && g.bytes().all(|b| ALPHABET.contains(&b)))
}

/// Bits of randomness in a key, for the record (ENK-OWN-015 asks for at least 80).
pub fn entropy_bits() -> f64 {
    SYMBOLS as f64 * (ALPHABET.len() as f64).log2()
}

